import java.security.MessageDigest;
import java.util.Set;

public class GravatarService {
    private static final Set<Integer> ALLOWED_SIZES = Set.of(32, 64, 128, 256, 512);
    private static final int DEFAULT_SIZE = 80;

    // Normalize MUST happen before hashing. Tradeoff: strictness vs usability.
    // We lowercase + trim so cache keys converge. Non-ASCII uses UTF-8 bytes.
    public static String emailHash(String email) {
        String norm = email == null ? "" : email.trim().toLowerCase();
        try {
            MessageDigest md = MessageDigest.getInstance("MD5");
            byte[] d = md.digest(norm.getBytes(java.nio.charset.StandardCharsets.UTF_8));
            StringBuilder sb = new StringBuilder();
            for (byte b : d) sb.append(String.format("%02x", b));
            return sb.toString();
        } catch (Exception e) { throw new IllegalStateException(e); }
    }

    public static int clampSize(int requested) {
        // Discrete sizes bound cache cardinality. Tradeoff: slight quality
        // mismatch vs 100x fewer cache keys than arbitrary s=1..2048.
        int best = DEFAULT_SIZE; int bestDiff = Integer.MAX_VALUE;
        for (int s : ALLOWED_SIZES) {
            int diff = Math.abs(s - requested);
            if (diff < bestDiff) { bestDiff = diff; best = s; }
        }
        return best;
    }

    public String variantKey(String emailHash, int size, long version) {
        return String.format("v1/%s/%d/v%d.jpg", emailHash, clampSize(size), version);
    }

    // Rating gate happens at variant serve time, not upload time alone,
    // so a site requesting r=g never gets an r-rated image even if cached.
    public boolean allowed(String imageRating, String requested) {
        return rank(imageRating) <= rank(requested);
    }
    private int rank(String r) {
        return switch (r == null ? "g" : r) {
            case "g" -> 0; case "pg" -> 1; case "r" -> 2; case "x" -> 3;
            default -> 0;
        };
    }
}

import hashlib

ALLOWED = {32, 64, 128, 256, 512}

def email_hash(email: str) -> str:
    norm = (email or "").strip().lower()
    return hashlib.md5(norm.encode("utf-8")).hexdigest()

def clamp_size(s: int) -> int:
    # Snap to nearest allowed size to protect hit rate.
    return min(ALLOWED, key=lambda a: abs(a - s))

def serve(hash_: str, size: int, rating: str, meta: dict, cache, store, cdn):
    # Single-flight + negative caching. Tradeoff: brief staleness
    # for missing users in exchange for surviving thundering herds.
    key = f"v1:{hash_}:{clamp_size(size)}:{meta.get('version', 0)}"
    hit = cache.get(key)
    if hit:
        return hit, "HIT"
    if not meta.get("has_image"):
        body = render_default(hash_, size)  # identicon / retro / 404
        cache.setex(key, 300, body)  # short TTL for negatives
        return body, "DEFAULT"
    body = store.get(f"variants/{key}.jpg")
    if body is None:
        orig = store.get(f"originals/{hash_}.jpg")
        body = resize(orig, clamp_size(size))  # done ONCE per version
        store.put(f"variants/{key}.jpg", body)
    cache.setex(key, 3600, body)
    return body, "MISS"
